update jj_collect.catalog as c
set data=c.data||jsonb_build_object('dedication_es',q.es,'dedication_en',q.en)
from quotes q
where c.data->>'collection'=q.collection
  and (c.data->>'art')::int=q.slot
  and (q.collection<>'navidad-jj' or (c.data->>'rarity')::int=3+q.side);

update jj_collect.catalog as c
set data=c.data||jsonb_build_object('dedication_es',q.es,'dedication_en',q.en)
from (values ('nu-869','Te prometo mirar las estrellas, Julie. Nomás deja de mirarme así primero.','I promise I’ll look at the stars, Julie. You just have to stop looking at me like that first.'),('nu-1004','Hicimos buen equipo en la guardia, doctora. ¿Te puedo invitar un café o se me nota demasiado?','We made a good team on shift, doctor. Can I buy you a coffee, or am I being too obvious?')) as q(id,es,en)
where c.id=q.id;